import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { createClient as createClient3 } from "npm:@supabase/supabase-js@^2.98.0";
import { z as z3 } from "npm:zod@^4.4.3";
var list_products_default = defineTool3({
  name: "list_products",
  title: "List store products",
  description: "List active products for a ShopBanao store by slug. Optional search filters by product name.",
  inputSchema: {
    slug: z3.string().trim().min(1).describe("Store slug the products belong to."),
    search: z3.string().trim().optional().describe("Optional case-insensitive substring match on product name."),
    limit: z3.number().int().min(1).max(50).optional().describe("Max rows to return (default 20).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ slug, search, limit }) => {
    const supabase = createClient3(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
      auth: { persistSession: false, autoRefreshToken: false }
    });
    const { data: store, error: sErr } = await supabase.from("stores").select("id").eq("slug", slug).eq("is_suspended", false).maybeSingle();
    if (sErr) return { content: [{ type: "text", text: sErr.message }], isError: true };
    if (!store) return { content: [{ type: "text", text: `No active store with slug "${slug}".` }], isError: true };
    let q = supabase.from("products").select("id, name, slug, description, price, sale_price, currency, stock_quantity, image_url, category").eq("store_id", store.id).eq("is_active", true).order("display_order", { ascending: true }).limit(limit ?? 20);
    if (search) q = q.ilike("name", `%${search}%`);
    const { data, error } = await q;
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? [], null, 2) }],
      structuredContent: { products: data ?? [] }
    };
  }
});

